  ('sambutan.sambutan_eyebrow', '01 — Pesan kepala sekolah', '2026-11-09 19:57:37'),
  ('sambutan.sambutan_title', 'Tumbuh menjadi pribadi<br><em>yang siap berkarya.</em>', '2026-11-09 19:57:37'),
  ('sambutan.sambutan_quote', 'Puji syukur kehadirat Allah SWT atas segala rahmat dan karunia-Nya. Website ini hadir sebagai sarana informasi, komunikasi, dan publikasi berbagai kegiatan serta perkembangan SMK ITABA kepada peserta didik, orang tua, masyarakat, dan dunia industri.', '2026-11-09 19:57:37'),
  ('sambutan.sambutan_body', 'SMK ITABA berkomitmen menyelenggarakan pendidikan yang memadukan kompetensi kejuruan, pendidikan karakter, dan nilai-nilai keislaman, sehingga mampu melahirkan lulusan yang berakhlak mulia, kompeten, mandiri, inovatif, dan siap menghadapi dunia kerja serta tantangan global.', '2026-11-09 19:57:37'),
  ('sambutan.pendidik_eyebrow', '02 — Warga sekolah', '2026-11-09 19:57:37'),
  ('sambutan.pendidik_title', 'Pendidik & tenaga<br><em>kependidikan.</em>', '2026-11-09 19:57:37'),
  ('sambutan.pendidik_text', 'Mendampingi secara profesional dalam bidang kurikulum, kesiswaan, hubungan industri, sarana, keahlian jurusan, hingga tata usaha dan data sekolah.', '2026-11-09 19:57:37'),
  ('kontak.meta_title', 'Kontak & Lokasi — SMK ITABA Gedangan', '2026-11-09 19:57:37'),
  ('kontak.meta_description', 'Kontak dan lokasi SMK ITABA (SMK Islam Tarbiyatul Badriyah): Jl. RA Mustika Tebel Timur, Desa Tebel, Gedangan, Sidoarjo. NPSN 69852106.', '2026-11-09 19:57:37'),
  ('kontak.hero_watermark', 'KONTAK', '2026-11-09 19:57:37'),
  ('kontak.hero_eyebrow', 'Kunjungi kami', '2026-11-09 19:57:37'),
  ('kontak.hero_title', 'Mari bertumbuh<br><em>bersama.</em>', '2026-11-09 19:57:37'),
  ('kontak.hero_text', 'Datang langsung ke SMK ITABA atau hubungi kami melalui telepon, email, dan media sosial resmi sekolah.', '2026-11-09 19:57:37'),
  ('kontak.cta_eyebrow', 'SPMB · Tahun Ajaran 2027/2028', '2026-11-09 19:57:37'),
  ('kontak.cta_title', 'Langkah pertamamu <em>dimulai di sini.</em>', '2026-11-09 19:57:37'),
  ('kontak.cta_text', 'Pendaftaran dapat dilakukan secara online atau diserahkan melalui SMP/MTs asal.', '2026-11-09 19:57:37'),
  ('spmb.meta_title', 'SPMB 2027/2028 — SMK ITABA Gedangan', '2026-11-09 19:57:37'),
  ('spmb.meta_description', 'Informasi SPMB SMK ITABA tahun ajaran 2027/2028: jadwal gelombang, rincian biaya seragam siap pakai, persyaratan, formulir online, dan kontak admin.', '2026-11-09 19:57:37'),
  ('spmb.hero_watermark', 'ITABA', '2026-11-09 19:57:37'),
  ('spmb.hero_eyebrow', 'Penerimaan Siswa Baru · Tahun Ajaran 2027/2028', '2026-11-09 19:57:37'),
  ('spmb.hero_title', 'Langkah pertamamu<br>dimulai <em>di sini.</em>', '2026-11-09 19:57:37'),
  ('spmb.hero_text', 'Pilih bidang keahlian DKV atau TKR, siapkan berkas pendaftaran, dan bergabung bersama keluarga besar SMK ITABA.', '2026-11-09 19:57:37'),
  ('spmb.hero_button', 'Isi formulir pendaftaran', '2026-11-09 19:57:37'),
  ('spmb.badge_image', 'assets/img/lencana-spmb.webp', '2026-11-09 19:57:37'),
  ('spmb.jadwal_eyebrow', '01 — Jadwal pendaftaran', '2026-11-09 19:57:37'),
  ('spmb.jadwal_title', 'Pilih gelombang<br><em>yang sesuai.</em>', '2026-11-09 19:57:37'),
  ('spmb.jadwal_text', 'Pastikan mengecek informasi terbaru dengan panitia. Pendaftaran dibuka melalui 3 gelombang terstruktur.', '2026-11-09 19:57:37'),
  ('spmb.biaya_eyebrow', '02 — Rincian biaya', '2026-11-09 19:57:37'),
  ('spmb.biaya_title', 'Rencanakan<br><em>pendaftaranmu.</em>', '2026-11-09 19:57:37'),
  ('spmb.biaya_text', 'Informasi biaya resmi berdasarkan dokumen SPMB SMK ITABA tahun ajaran 2027/2028.', '2026-11-09 19:57:37'),
  ('spmb.biaya_cakupan', '<strong>Cakupan Biaya:</strong> Biaya gelombang di atas sudah mencakup <strong>5 stel seragam (sudah terjahit dan siap pakai)</strong>, atribut seragam lengkap, dan kegiatan MPLS (Masa Pengenalan Lingkungan Sekolah).', '2026-11-09 19:57:37'),
  ('spmb.biaya_spp', 'SPP diperkirakan tetap Rp200.000/bulan (mengacu pada bulan Juli 2026). Mohon konfirmasi nominal tahun ajaran 2027/2028 kepada panitia saat pendaftaran.', '2026-11-09 19:57:37'),
  ('spmb.syarat_eyebrow', '03 — Persyaratan', '2026-11-09 19:57:37'),
  ('spmb.syarat_title', 'Siapkan berkas<br><em>pendaftaran.</em>', '2026-11-09 19:57:37'),
  ('spmb.syarat_text', 'Isi formulir pendaftaran dan serahkan dengan melampirkan berkas persyaratan berikut (fotokopi masing-masing 2 lembar, kecuali pas foto).', '2026-11-09 19:57:37'),
  ('spmb.daftar_eyebrow', '04 — Daftar dan bertanya', '2026-11-09 19:57:37'),
  ('spmb.daftar_title', 'Semua informasi<br><em>dalam genggaman.</em>', '2026-11-09 19:57:37'),
  ('spmb.daftar_text', 'Scan QR code untuk langsung membuka formulir pendaftaran online atau menghubungi admin SPMB.', '2026-11-09 19:57:37'),
