  ('stats', 30, 1, '{\"value\":\"14+ Fasilitas\",\"label\":\"Gedung 3 Lantai · Lab AC · Wi-Fi 120 Mbps\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('stats', 40, 1, '{\"value\":\"15 Ekskul & Komunitas\",\"label\":\"Robotika, Futsal, Silat, Game 3D, Dll\",\"accent\":\"1\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('program', 10, 1, '{\"nama\":\"Desain Komunikasi Visual\",\"singkatan\":\"DKV\",\"slug\":\"dkv\",\"kode\":\"01 / KREATIF DIGITAL\",\"gaya\":\"dkv\",\"icon\":\"pen\",\"simbol\":\"✳\",\"tagline\":\"“Kreatif Berkarya, Siap Menghadapi Industri Global”\",\"ringkasan\":\"Kreatif berkarya di bidang desain grafis, ilustrasi, foto, video, animasi, UI/UX, serta peluang magang dan karier ke Jepang.\",\"deskripsi\":\"Program keahlian yang membekali peserta didik dengan kemampuan menciptakan karya visual untuk kebutuhan komunikasi, promosi, branding, media digital, dan industri kreatif modern.\",\"kompetensi\":\"Desain grafis & ilustrasi\\nFotografi & videografi\\nAnimasi & motion graphics\\nDesain UI/UX\\nBranding & desain kemasan\\nPenguasaan software desain\",\"peluang\":\"Desainer Grafis\\nIllustrator\\nContent Creator\\nVideographer\\nEditor Video\\nAnimator\\nUI/UX Designer\\nPhotographer\\nSocial Media Designer\\nWirausaha Kreatif\",\"highlight_judul\":\"Peluang Magang & Karier ke Jepang\",\"highlight_teks\":\"Lulusan DKV berpeluang mengikuti program magang dan bekerja di industri kreatif luar negeri, termasuk peluang kerja sama penyaluran tenaga kerja ke Jepang sesuai kualifikasi dan persyaratan.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('program', 20, 1, '{\"nama\":\"Teknik Kendaraan Ringan\",\"singkatan\":\"TKR\",\"slug\":\"tkr\",\"kode\":\"02 / TEKNOLOGI OTOMOTIF\",\"gaya\":\"tkr\",\"icon\":\"wrench\",\"simbol\":\"⌁\",\"tagline\":\"“Terampil Menguasai Teknologi Otomotif, Siap Kerja dan Berkarier Global”\",\"ringkasan\":\"Kuasai perawatan mesin, kelistrikan, diagnosis kendaraan ringan, dan raih peluang karier hingga perusahaan otomotif Jepang.\",\"deskripsi\":\"Program keahlian yang membekali peserta didik dengan keterampilan dalam perawatan, perbaikan, diagnosis, dan pemeliharaan kendaraan ringan serta teknologi otomotif modern.\",\"kompetensi\":\"Perawatan mesin kendaraan\\nSistem kelistrikan otomotif\\nPemindah tenaga, chassis & rem\\nSistem kemudi & AC kendaraan\\nDiagnosis kerusakan & alat ukur\\nPenerapan K3 dan budaya industri\",\"peluang\":\"Teknisi / Mekanik Otomotif\\nService Advisor\\nTeknisi Bengkel Resmi\\nTeknisi Kendaraan Ringan\\nWirausaha Bengkel Otomotif\",\"highlight_judul\":\"Peluang Magang & Karier di Perusahaan Otomotif Jepang\",\"highlight_teks\":\"Lulusan TKR memiliki akses peluang magang ke Jepang dan mengembangkan karier hingga bekerja di perusahaan otomotif Jepang melalui program kemitraan dan seleksi yang tersedia.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
