  ('rutinitas', 10, 1, '{\"waktu\":\"Pagi Hari\",\"judul\":\"Sholat Dhuha Berjamaah\",\"deskripsi\":\"Membangun kedisiplinan spiritual dan menanamkan kebiasaan mendekatkan diri kepada Allah SWT sebelum memulai seluruh aktivitas belajar.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('rutinitas', 20, 1, '{\"waktu\":\"Pagi Hari\",\"judul\":\"Yasin & Tahlil Bersama\",\"deskripsi\":\"Melestarikan tradisi keagamaan Ahlussunnah wal Jama\'ah untuk memupuk kebersamaan, ketenangan jiwa, serta mendoakan kebaikan bagi sesama.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('rutinitas', 30, 1, '{\"waktu\":\"Pukul 08.10 WIB\",\"judul\":\"Mengaji & Masuk Kelas\",\"deskripsi\":\"Tadarus Al-Qur\'an dilanjutkan pembelajaran mata pelajaran umum serta praktik produktif kejuruan di bengkel dan lab komputer.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('nilai', 10, 1, '{\"judul\":\"Kompetensi\",\"icon\":\"medal\",\"deskripsi\":\"Belajar melalui teori mendalam dan praktik nyata sesuai standar kebutuhan industri kerja.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('nilai', 20, 1, '{\"judul\":\"Karakter\",\"icon\":\"shield-check\",\"deskripsi\":\"Disiplin, tanggung jawab, kepedulian sosial, dan pembinaan akhlak berlandaskan nilai keislaman.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('nilai', 30, 1, '{\"judul\":\"Masa Depan\",\"icon\":\"compass\",\"deskripsi\":\"Siap bekerja di industri, siap berwirausaha mandiri, serta mampu bersaing hingga kancah internasional.\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
