  ('ekskul', 10, 1, '{\"judul\":\"Teknologi & Kreatif Digital\",\"subjudul\":\"Eksplorasi software, robotik & multimedia\",\"icon\":\"terminal\",\"aksen\":\"1\",\"daftar\":\"Robotika & Virtual Metavers | Tech\\nAnimasi Game 2D/3D | Game Dev\\nVideo & Fotografi | Media\\nDesain Grafis | Creative\\nTEAM DIGITABA | Komunitas\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('ekskul', 20, 1, '{\"judul\":\"Olahraga & Bela Diri\",\"subjudul\":\"Kesehatan fisik, sportivitas & seni silat\",\"icon\":\"ball\",\"aksen\":\"1\",\"daftar\":\"Futsal | Olahraga\\nBulu Tangkis | Olahraga\\nPencak Silat Pagar Nusa | Bela Diri Tradisi\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('ekskul', 30, 1, '{\"judul\":\"Kepemimpinan, Seni & Bahasa\",\"subjudul\":\"Membentuk karakter, wawasan & kepercayaan diri\",\"icon\":\"star\",\"daftar\":\"Pramuka | Wajib / Karakter\\nTeater | Seni Peran\\nDEKADE TEAM | Komunitas Kreasi\\nEnglish Conversation | Bahasa Global\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('ekskul', 40, 1, '{\"judul\":\"Sosial, Alam & Keahlian\",\"subjudul\":\"Kepedulian sosial, lingkungan hidup & skill nyata\",\"icon\":\"shield\",\"daftar\":\"Pencinta Alam SMK ITABA (SEMKIPALA) | Petualang Alam\\nPeduli Lingkungan Masyarakat | Aksi Sosial\\nMengemudi | Life Skill Praktis\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 10, 1, '{\"nama\":\"Umi Hanik, M.Pd\",\"jabatan\":\"Waka Kurikulum\",\"foto\":\"assets/img/umi-hanik.webp\",\"featured\":\"1\",\"pesan\":\"“Berkomitmen menghadirkan proses pembelajaran yang terarah, adaptif, dan relevan dengan kebutuhan dunia kerja serta mengintegrasikan pendidikan karakter dan nilai keislaman.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 20, 1, '{\"nama\":\"Muis Lidinillah, S.Pd\",\"jabatan\":\"Waka Kesiswaan & Ketua PPDB\",\"foto\":\"assets/img/muis-lidinillah.webp\",\"pesan\":\"“Mendampingi potensi siswa dalam kedisiplinan, kepemimpinan, dan tanggung jawab agar tumbuh menjadi pribadi yang berakhlak mulia dan berprestasi.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 30, 1, '{\"nama\":\"Nurul Abshori, M.Pd\",\"jabatan\":\"Wakil Hubinmas\",\"foto\":\"assets/img/nurul-abshori.webp\",\"pesan\":\"“Membangun sinergi kuat dengan dunia industri untuk memperluas peluang PKL, magang, sertifikasi, hingga karier internasional bagi para lulusan.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 40, 1, '{\"nama\":\"Bambang Purwanto, M.Pd\",\"jabatan\":\"Waka Sarana & Prasarana\",\"foto\":\"assets/img/bambang-purwanto.webp\",\"pesan\":\"“Menyediakan fasilitas dan sarana belajar yang nyaman, aman, serta sesuai standar kebutuhan industri modern untuk menunjang praktik siswa.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 50, 1, '{\"nama\":\"Arifin, S.Ds\",\"jabatan\":\"Kepala Program DKV\",\"foto\":\"assets/img/arifin.webp\",\"pesan\":\"“Mengembangkan kreativitas visual berbasis proyek nyata untuk mencetak insan kreatif digital yang inovatif dan siap bersaing di industri global.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 60, 1, '{\"nama\":\"Kunto Wibisono, S.T.\",\"jabatan\":\"Kepala Program TKR\",\"foto\":\"assets/img/kunto-wibisono.webp\",\"pesan\":\"“Membekali keterampilan teknis otomotif, K3, dan etos kerja profesional serta membuka peluang karier hingga perusahaan otomotif Jepang.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
  ('guru', 70, 1, '{\"nama\":\"Zahrotul Ilmi, S.Kom.\",\"jabatan\":\"Operator Sekolah (Dapodik)\",\"foto\":\"assets/img/zahrotul-ilmi.webp\",\"pesan\":\"“Mendukung pengelolaan data dan sistem informasi sekolah secara tertib, akurat, dan transparan demi menunjang kualitas layanan pendidikan.”\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
