  ('prestasi', 10, 1, '{\"judul\":\"Lomba Kompetensi Siswa (LKS) Dikmen Kabupaten Sidoarjo 2025\",\"kategori\":\"kejuruan\",\"peringkat\":\"🏆 Juara 2 & 3\",\"gaya_peringkat\":\"\",\"meta\":\"Kabupaten Sidoarjo · Feb 2025\",\"deskripsi\":\"Dua siswa SMK ITABA sekaligus naik podium pada LKS Dikmen 18–21 Februari 2025: <strong>Juara 2 bidang Automobile Technology</strong> dan <strong>Juara 3 bidang Teknik Perancangan Model 3D (3D Game Art)</strong>. Bukti bahwa jurusan TKR dan DKV sama-sama bersaing di level kabupaten.\",\"tags\":\"TKR, DKV, LKS\",\"foto\":\"assets/img/prestasi/lks-2025-1.webp\",\"alt\":\"Dua siswa SMK ITABA memegang piala Juara 2 dan Juara 3 LKS Dikmen Kabupaten Sidoarjo 2025\",\"caption\":\"Juara 2 Automobile Technology & Juara 3 Teknik Perancangan Model 3D (3D Game Art) — LKS Dikmen Kabupaten Sidoarjo, 18–21 Februari 2025\",\"foto2\":\"assets/img/prestasi/lks-2025-2.webp\",\"caption2\":\"Foto bersama pembina dan juri LKS Dikmen Kabupaten Sidoarjo 2025\",\"featured\":\"1\",\"beranda\":\"1\",\"beranda_label\":\"LKS Kabupaten 2025\",\"beranda_judul\":\"Juara 2 Otomotif & Juara 3 3D Game Art\",\"beranda_sub\":\"TKR & DKV · Tingkat Kabupaten Sidoarjo\"}', '2026-11-09 19:57:37', '2026-11-09 19:57:37'),
